package vn.rtr.aeris.native97;
import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Byte-exact diagnostic generations. No rotation deletes, no overwrite of previous generations. */
public final class UiJournal96{
 public static final long CAP=2L*1024*1024,TOTAL=16L*1024*1024;public static final int GENERATIONS=16;private final Path root,file;private int written=0;private long bytes=0;
 public UiJournal96(Path root,String id)throws IOException{if(!id.matches("[a-f0-9-]{36}")||Files.isSymbolicLink(root))throw new IOException("UI96_PATH");Files.createDirectories(root);this.root=root;File[] files=root.toFile().listFiles();if(files==null)throw new IOException("UI96_LIST");int count=0;for(File f:files){if(Files.isSymbolicLink(f.toPath())||!f.isFile())throw new IOException("UI96_FOREIGN");if(f.getName().endsWith(".jsonl"))count++;}if(count>=GENERATIONS)throw new IOException("UI96_GENERATION_QUOTA_NO_DELETE");file=root.resolve(id+".jsonl");Files.createFile(file);Path pointer=root.resolve("CURRENT");Path stage=root.resolve("CURRENT-"+id);try(FileOutputStream out=new FileOutputStream(stage.toFile())){out.write(id.getBytes(StandardCharsets.US_ASCII));out.getFD().sync();}Files.move(stage,pointer,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
 public synchronized boolean append(String receipt)throws IOException{byte[] line=(receipt+"\n").getBytes(StandardCharsets.UTF_8);if(line.length>65536||bytes+line.length>CAP||written>=2048)return false;long total=0;try(DirectoryStream<Path> entries=Files.newDirectoryStream(root)){for(Path p:entries){if(Files.isSymbolicLink(p)||!Files.isRegularFile(p))throw new IOException("UI96_FOREIGN");total+=Files.size(p);}}if(total+line.length>TOTAL||root.toFile().getUsableSpace()<DraftStore.RESERVE+line.length)return false;try(FileOutputStream out=new FileOutputStream(file.toFile(),true)){out.write(line);out.getFD().sync();}bytes+=line.length;written++;return true;}
 public String path(){return file.getFileName().toString();}public long bytes(){return bytes;}
}
